namespace Calc;

public static class Calculator
{
    public static int Add(int a, int b) => a + b;

    public static int Clamp(int value, int low, int high)
    {
        if (value < low)
        {
            return low;
        }
        if (value > high)
        {
            return high;
        }
        return value;
    }

    public static int Sign(int x)
    {
        if (x > 0)
        {
            return 1;
        }
        if (x < 0)
        {
            return -1;
        }
        return 0;
    }
}
